nth_name, l1_category, category, meta1, meta2, meta3, repeat_type, qty from pipeline_base where status_clean <> \'fabric placed\' and qty is not null ), pipeline as ( select month_name, l1_category, category, meta1, meta2, meta3, sum(case when repeat_type = \'REPEAT\' then qty else 0 end) as repeats_in_pipeline, sum(qty) as total_in_pipeline from pipeline_cleaned where month_name is not null group by 1,2,3,4,5,6 ), putaway_raw as ( select m.month_name, upper( trim( regexp_replace( replace(p.\"Item Type skuCode\", \' \', \'\'), \'-[^-]+$\', \'\' ) ) ) as sku_group, sum(p.\"PUTAWAY_COMPLETED_QUANTITY\") as inwarded_qty from snitch_db.maplemonk.putaway_tracking p join month_map m on p.putaway_updated::date >= m.start_date and p.putaway_updated::date < m.end_date where lower(p.final_type) = \'new inward\' group by 1,2 ), inwarded as ( select p.month_name, m.l1_category, m.category, case when m.l1_category = \'LUXE\' then null else m.meta1 end as meta1, case when m.l1_category = \'LUXE\' then null else m.meta2 end as meta2, case when m.l1_category = \'LUXE\' then null else m.meta3 end as meta3, sum(p.inwarded_qty) as inwarded from putaway_raw p left join meta_map m on upper( iff( upper(replace(p.sku_group, \' \', \'\')) like \'MP%\' or upper(replace(p.sku_group, \' \', \'\')) like \'4C-%\', regexp_replace( replace(p.sku_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), regexp_replace(replace(p.sku_group, \' \', \'\'), \'-.*$\', \'\') ) ) = m.sku_group_clean group by 1,2,3,4,5,6 ), final as ( select coalesce(d.month_name, rp.month_name, pl.month_name, pi.month_name, i.month_name) as month_name, coalesce(d.l1_category, rp.l1_category, pl.l1_category, pi.l1_category, i.l1_category) as l1_category, coalesce(d.category, rp.category, pl.category, pi.category, i.category) as category, coalesce(d.meta1, rp.meta1, pl.meta1, pi.meta1, i.meta1) as meta1, coalesce(d.meta2, rp.meta2, pl.meta2, pi.meta2, i.meta2) as meta2, coalesce(d.meta3, rp.meta3, pl.meta3, pi.meta3, i.meta3) 