coalesce(i.meta3, \'\') ) select * from final order by case month_name when \'APRIL\' then 1 when \'MAY\' then 2 when \'JUNE\' then 3 when \'JULY\' then 4 when \'AUGUST\' then 5 when \'SEPTEMBER\' then 6 when \'OCTOBER\' then 7 when \'NOVEMBER\' then 8 when \'DECEMBER\' then 9 when \'JANUARY\' then 10 when \'FEBRUARY\' then 11 end, l1_category, category, meta1, meta2, meta3;",
